input.command:
cd /tmp
cat > /tmp/tt.sh <<'EOF'
#!/bin/bash
w="$1"
g=$(/tmp/p.sh "    $w" | tr -d '\n'); g=${g#*<code>}; g=${g%%</code>*}
t=$(/tmp/p.sh $'    :::teratermmacro\n    '"$w" | tr -d '\n'); t=${t#*<code>}; t=${t%%</code>*}
printf '%-12s guess=%-46s teraterm=%s\n' "$w" "$g" "$t"
EOF
chmod +x /tmp/tt.sh
printf '%s\n' if while for end return goto call then else break continue do exit loop next send sendln wait connect pause strlen messagebox include until show tool var const function type enum package class module role grammar | xargs -P 12 -n 1 /tmp/tt.sh 2>/dev/null | sort
